1	"use server";
2	
3	import { db } from "./db";
4	import { requireArea } from "./rbac";
5	import { revalidatePath } from "next/cache";
6	
7	/**
8	 * Admin actions for the outbound-abuse queue. Fleet-area staff review alerts
9	 * raised by worker/abuse.ts and can acknowledge, resolve, or suspend the server.
10	 */
11	
12	export async function acknowledgeAlert(id: string): Promise<{ ok?: boolean; error?: string }> {
13	  const admin = await requireArea("fleet");
14	  await db.abuseAlert.update({ where: { id }, data: { status: "ACKNOWLEDGED" } });
15	  // Triaging an abuse case changes a customer's standing in the queue; record WHO
16	  // did it, the same way suspendForAbuse below does. Was unlogged.
17	  await db.auditLog.create({ data: { userId: admin.id, action: "abuse.acknowledge", detail: id } });
18	  revalidatePath("/admin/abuse");
19	  return { ok: true };
20	}
21	
22	export async function resolveAlert(id: string): Promise<{ ok?: boolean; error?: string }> {
23	  const admin = await requireArea("fleet");
24	  await db.abuseAlert.update({ where: { id }, data: { status: "RESOLVED", resolvedAt: new Date() } });
25	  // Closing an abuse case clears it from the queue — an attributable action.
26	  await db.auditLog.create({ data: { userId: admin.id, action: "abuse.resolve", detail: id } });
27	  revalidatePath("/admin/abuse");
28	  return { ok: true };
29	}
30	
31	/** Suspend the server behind an alert (enqueues a SUSPEND job) and mark it ACTIONED. */
32	export async function suspendForAbuse(id: string): Promise<{ ok?: boolean; error?: string }> {
33	  const admin = await requireArea("fleet");
34	  const alert = await db.abuseAlert.findUnique({ where: { id } });
35	  if (!alert) return { error: "Alert not found." };
36	  const server = await db.server.findUnique({ where: { id: alert.serverId } });
37	  if (!server) return { error: "Server no longer exists." };
38	  if (server.status !== "SUSPENDED") {
39	    // Record WHY before enqueuing. Without it the billing engine cannot tell an
40	    // abuse suspension from an unpaid one, and two things go wrong: the overdue
41	    // sweep eventually DELETES the server as a non-payer (the renewal sweep skips
42	    // suspended servers, so it was never billed or warned in the meantime), and
43	    // the customer can lift the suspension themselves by clicking "Renew now".
44	    await db.server.update({
45	      where: { id: server.id },
46	      data: {
47	        suspendReason: "ABUSE",
48	        suspendedNote: "suspended pending an abuse review — contact support",
49	      },
50	    });
51	    await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
52	  }
53	  await db.abuseAlert.update({ where: { id }, data: { status: "ACTIONED" } });
54	  await db.auditLog.create({
55	    data: { userId: admin.id, action: "abuse.suspend", detail: `${server.hostname} (${alert.kind}) — ${alert.detail}` },
56	  });
57	  revalidatePath("/admin/abuse");
58	  return { ok: true };
59	}
