1	import { SignJWT, jwtVerify, type JWTPayload } from "jose";
2	import { cookies } from "next/headers";
3	import { cache } from "react";
4	import { db } from "./db";
5	import { getSettingInt } from "./settings";
6	import type { User } from "@prisma/client";
7	
8	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
9	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
10	
11	export async function createSession(userId: string) {
12	  // Session lifetime is admin-configurable (`session_length_days`, default 30).
13	  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
14	  const days = Math.max(1, await getSettingInt("session_length_days", 30));
15	  // Embed the account's current sessionVersion so a bump (password change/reset)
16	  // invalidates every previously-issued token. Missing => treated as 0.
17	  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
18	  // `typ` distinguishes this from the impersonation token below. Both are signed
19	  // with the SAME secret, so without it the two are interchangeable strings —
20	  // see the note on `assertSessionToken`.
21	  const token = await new SignJWT({ sub: userId, sv: acct?.sessionVersion ?? 0, typ: "session" })
22	    .setProtectedHeader({ alg: "HS256" })
23	    .setIssuedAt()
24	    .setExpirationTime(`${days}d`)
25	    .sign(secret);
26	  const jar = await cookies();
27	  // Secure in production regardless of COOKIE_SECURE, matching the impersonation
28	  // cookie — a deploy that forgets COOKIE_SECURE=1 must not ship a non-Secure
29	  // session cookie. Local http dev stays non-secure (NODE_ENV !== "production").
30	  const secure = process.env.NODE_ENV === "production";
31	  jar.set(COOKIE, token, {
32	    httpOnly: true,
33	    sameSite: "lax",
34	    secure,
35	    maxAge: 60 * 60 * 24 * days,
36	    path: "/",
37	  });
38	  // Non-sensitive, JS-readable flag so the (static) marketing header can show
39	  // "Dashboard" instead of "Login/Get started" for a signed-in visitor. Carries
40	  // no identity — just presence. Always cleared alongside the session cookie.
41	  jar.set("nxeon_authed", "1", {
42	    httpOnly: false,
43	    sameSite: "lax",
44	    secure,
45	    maxAge: 60 * 60 * 24 * days,
46	    path: "/",
47	  });
48	}
49	
50	export async function destroySession() {
51	  const jar = await cookies();
52	  jar.delete(COOKIE);
53	  jar.delete("nxeon_authed");
54	}
55	
56	/**
57	 * Is this payload allowed to act as a SESSION, as opposed to an impersonation
58	 * grant?
59	 *
60	 * Both cookies are HS256 over the same `AUTH_SECRET`, so as far as `jwtVerify`
61	 * is concerned an impersonation token is a perfectly valid session token — the
62	 * only difference was which claims happened to be present, and nothing checked.
63	 * Moving the value of `nxeon_session_imp` into `nxeon_session` therefore
64	 * produced a REAL session as the impersonated customer: not flagged as
65	 * impersonation, so `impersonating()` returns null, the banner does not render,
66	 * and `audit()` in lib/actions.ts stops appending `actingAdmin=…` — every
67	 * subsequent action is recorded as the customer's own. For a platform holding
68	 * customer servers and saved cards, "an admin can act as a customer with no
69	 * trace" is the accountability failure that matters even though the admin was
70	 * already privileged.
71	 *
72	 * An impersonation grant is also the weaker credential by design (2h, no
73	 * `sessionVersion`), so it must not be promotable into the stronger one: it
74	 * carries no `sv`, which `realUser` reads as 0, and 0 is the DEFAULT
75	 * sessionVersion — so for any account that has never changed its password the
76	 * promotion also survives every existing revocation check.
77	 *
78	 * Old session tokens minted before `typ` existed carry neither claim and stay
79	 * valid, so nobody is signed out by this.
80	 */
81	function assertSessionToken(payload: JWTPayload): boolean {
82	  if (payload.adminId !== undefined) return false;
83	  return payload.typ === undefined || payload.typ === "session";
84	}
85	
86	/**
87	 * Lightweight "is there a valid session?" check — verifies the session JWT
88	 * (signature + expiry) WITHOUT a DB round-trip. Used by /api/auth/status so the
89	 * (static) marketing header can authoritatively show "Back to portal" even when
90	 * the non-httpOnly `nxeon_authed` flag cookie is missing or stale.
91	 *
92	 * KNOWN AND ACCEPTED LIMIT: with no DB round-trip this cannot see a
93	 * `sessionVersion` bump or a suspension, so for a revoked session it can still
94	 * answer `true`. That is deliberate — this endpoint is hit by the marketing
95	 * header on every page view, and it decides nothing but which of two links to
96	 * draw. Every route that actually grants access goes through `realUser`, which
97	 * does check both. Do not reach for this function to authorise anything.
98	 */
99	export async function isSignedIn(): Promise<boolean> {
100	  const jar = await cookies();
101	  const token = jar.get(COOKIE)?.value;
102	  if (!token) return false;
103	  try {
104	    const { payload } = await jwtVerify(token, secret);
105	    return assertSessionToken(payload);
106	  } catch {
107	    return false;
108	  }
109	}
110	
111	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
112	
113	/** The real signed-in account, ignoring any impersonation. */
114	export const realUser = cache(async (): Promise<User | null> => {
115	  const jar = await cookies();
116	  const token = jar.get(COOKIE)?.value;
117	  if (!token) return null;
118	  try {
119	    const { payload } = await jwtVerify(token, secret);
120	    if (!payload.sub) return null;
121	    // An impersonation grant is not a session (see assertSessionToken).
122	    if (!assertSessionToken(payload)) return null;
123	    const user = await db.user.findUnique({ where: { id: payload.sub } });
124	    if (!user || user.suspended) return null;
125	    // Session revocation: a token is only valid while its embedded version matches
126	    // the account's current sessionVersion. Older tokens without `sv` count as 0,
127	    // so accounts that never bumped stay logged in (backward-compatible).
128	    const tokenVer = typeof payload.sv === "number" ? payload.sv : 0;
129	    if (tokenVer !== (user.sessionVersion ?? 0)) return null;
130	    return user;
131	  } catch {
132	    return null;
133	  }
134	});
135	
136	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
137	export const currentUser = cache(async (): Promise<User | null> => {
138	  const real = await realUser();
139	  if (!real) return null;
140	  if (real.role === "ADMIN") {
141	    const jar = await cookies();
142	    const imp = jar.get(IMP_COOKIE)?.value;
143	    if (imp) {
144	      try {
145	        const { payload } = await jwtVerify(imp, secret);
146	        if (payload.typ === "imp" && payload.adminId === real.id && typeof payload.sub === "string") {
147	          const target = await db.user.findUnique({ where: { id: payload.sub } });
148	          // The token outlives the checks `impersonateUser` made when it minted
149	          // it (2h), so they are re-made here against the CURRENT row rather
150	          // than trusted from the past:
151	          //
152	          //  - suspended: `realUser` refuses to hand out a session for a
153	          //    suspended account, and impersonation must not be a side door that
154	          //    resurrects one. Reviewing a suspended abuser's account is a
155	          //    read-only job; it must not come with the ability to act as them.
156	          //  - ADMIN: refused at mint time, but a customer promoted DURING an
157	          //    open impersonation would otherwise turn the impersonator's
158	          //    `currentUser()` into an ADMIN — and `requireAdmin` is built on
159	          //    `currentUser`, so admin actions would run attributed to the
160	          //    promoted account instead of the person taking them. The rule that
161	          //    admins refuse to act while impersonating depends on this.
162	          //
163	          // Falling through to the real admin is the safe failure: they are
164	          // simply themselves again, which is visible on screen.
165	          if (target && !target.suspended && target.role !== "ADMIN") return target;
166	        }
167	      } catch {
168	        /* expired/invalid impersonation — fall through to real user */
169	      }
170	    }
171	  }
172	  return real;
173	});
174	
175	/** Non-null when the current request is an admin impersonating a customer. */
176	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
177	  const real = await realUser();
178	  if (!real || real.role !== "ADMIN") return null;
179	  const target = await currentUser();
180	  if (!target || target.id === real.id) return null;
181	  return { admin: real, target };
182	});
183	
184	export async function setImpersonation(targetUserId: string) {
185	  const real = await realUser();
186	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
187	  // `typ: "imp"` marks this as a grant, never a session (see assertSessionToken).
188	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id, typ: "imp" })
189	    .setProtectedHeader({ alg: "HS256" })
190	    .setIssuedAt()
191	    .setExpirationTime("2h")
192	    .sign(secret);
193	  const jar = await cookies();
194	  jar.set(IMP_COOKIE, token, {
195	    httpOnly: true,
196	    sameSite: "lax",
197	    secure: process.env.NODE_ENV === "production",
198	    path: "/",
199	    maxAge: 7200,
200	  });
201	}
202	
203	export async function clearImpersonation() {
204	  const jar = await cookies();
205	  jar.delete(IMP_COOKIE);
206	}
207	
208	/**
209	 * Guard for wallet-debit / paid actions: refuse to run while an admin is
210	 * impersonating a customer. Keeps money movements attributable to the account
211	 * holder and prevents an admin from spending a customer's balance on their behalf.
212	 * Throws a friendly, user-facing error. Call at the top of every spend path.
213	 */
214	export async function assertNotImpersonating(): Promise<void> {
215	  const imp = await impersonating();
216	  if (imp) {
217	    throw new Error(
218	      "This action is disabled while impersonating a customer. Stop impersonating to continue.",
219	    );
220	  }
221	}
222	
223	export async function requireUser(): Promise<User> {
224	  const user = await currentUser();
225	  if (!user) throw new Error("UNAUTHORIZED");
226	  return user;
227	}
228	
229	export async function requireAdmin(): Promise<User> {
230	  const user = await requireUser();
231	  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
232	  return user;
233	}
234	
235	/**
236	 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
237	 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
238	 * per-area gating lives in lib/rbac.ts (`requireArea`).
239	 */
240	export async function requireStaff(): Promise<User> {
241	  const user = await realUser();
242	  if (!user) throw new Error("UNAUTHORIZED");
243	  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
244	    throw new Error("FORBIDDEN");
245	  }
246	  return user;
247	}
248

1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireArea } from "./rbac";
6	import { nodeTargets, BACKUP_STALE_MS } from "./monitoring";
7	import { pveFor, listBackups, listBackupsOn } from "./proxmox";
8	import { backupScheduleHealth, type BackupHealth } from "./backup-verify";
9	import {
10	  joinArchives,
11	  summarizeArchives,
12	  serversWithNoRecentBackup,
13	  vmidFromVolid,
14	  type NodeArchive,
15	  type ServerLite,
16	  type JoinedArchive,
17	  type BackupTotals,
18	  type AtRiskServer,
19	} from "@/app/admin/backups/logic";
20	
21	/**
22	 * ADMIN fleet-wide backup actions.
23	 *
24	 * `"use server"` means every export here is a network-reachable endpoint, so
25	 * each one re-checks `requireArea("fleet")` INSIDE the function — a dropped guard
26	 * on the restore action would be a cross-tenant data-DESTRUCTION hole, not just a
27	 * data leak. Backups are live-from-Proxmox (there is no Backup table): we
28	 * enumerate every node's `backup` storage and join each archive's vmid to a
29	 * Server row, exactly as the customer surface and the admin monitoring page do.
30	 *
31	 * HONESTY: a node that cannot be enumerated is reported as `reachable: false`,
32	 * never dropped. A silently missing node reads as "these servers have no
33	 * backups", which at restore time is the most dangerous lie this page could tell.
34	 */
35	
36	// ---------------------------------------------------------------------------
37	// Serializable view returned to the (client) admin table
38	// ---------------------------------------------------------------------------
39	
40	/** Per-node enumeration outcome — honest about nodes we could not read. */
41	export type NodeEnum = { label: string; reachable: boolean; archiveCount: number };
42	
43	/** Per-server backup-schedule health row (dates as ISO strings for the client). */
44	export type ServerScheduleRow = {
45	  id: string;
46	  vmid: number | null;
47	  hostname: string;
48	  email: string;
49	  nodeLabel: string | null;
50	  status: string;
51	  autoBackup: boolean;
52	  backupIntervalHours: number | null;
53	  lastAutoBackup: string | null;
54	  health: BackupHealth;
55	};
56	
57	export type AdminBackupsView = {
58	  nodes: NodeEnum[];
59	  anyNodeUnreachable: boolean;
60	  archives: JoinedArchive[];
61	  summary: BackupTotals;
62	  atRisk: AtRiskServer[];
63	  servers: ServerScheduleRow[];
64	  staleMs: number;
65	};
66	
67	/**
68	 * Enumerate every node's `backup` storage, join each archive to its owning
69	 * Server, and compute the summary + at-risk + per-server schedule health.
70	 */
71	export async function listAllBackups(): Promise<AdminBackupsView> {
72	  await requireArea("fleet");
73	
74	  const [targets, servers] = await Promise.all([
75	    nodeTargets(),
76	    db.server.findMany({
77	      where: { vmid: { not: null } },
78	      select: {
79	        id: true,
80	        vmid: true,
81	        hostname: true,
82	        status: true,
83	        autoBackup: true,
84	        backupIntervalHours: true,
85	        lastAutoBackup: true,
86	        user: { select: { email: true } },
87	        node: { select: { name: true } },
88	      },
89	    }),
90	  ]);
91	
92	  // Read each node's backup-storage content. This is the same read-only
93	  // `/storage/backup/content` call `listBackupsOn`/`backupSummary` make; we read
94	  // the FULL listing (no vmid filter) because orphan archives — whose vmid has no
95	  // Server — must be surfaced, and a vmid-filtered read can never see them.
96	  //
97	  // Tries every storage `nodeTargets()` lists for that node, not a hardcoded
98	  // "backup" — the vzdump-archive storage name isn't uniform across nodes (the
99	  // primary's happens to be literally named `backup`; a Hetzner-onboarded node's
100	  // is its own storageHdd, e.g. `vmdata-hdd`). A node is only reported
101	  // unreachable if EVERY one of its storages failed — one non-backup-capable
102	  // storage failing (e.g. a pure-ISO storage) is not the node being down.
103	  const nodes: NodeEnum[] = [];
104	  const entries: NodeArchive[] = [];
105	  let anyNodeUnreachable = false;
106	  for (const t of targets) {
107	    let count = 0;
108	    let anyStorageOk = false;
109	    for (const storage of t.storages) {
110	      try {
111	        const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/${storage}/content`, {
112	          content: "backup",
113	        });
114	        anyStorageOk = true;
115	        for (const raw of items ?? []) {
116	          if (typeof raw?.volid !== "string") continue;
117	          entries.push({
118	            nodeLabel: t.label,
119	            raw: {
120	              volid: raw.volid,
121	              vmid: typeof raw.vmid === "number" ? raw.vmid : undefined,
122	              ctime: typeof raw.ctime === "number" ? raw.ctime : undefined,
123	              size: typeof raw.size === "number" ? raw.size : undefined,
124	            },
125	          });
126	          count++;
127	        }
128	      } catch {
129	        // this storage isn't backup-content-capable on this node — try the next
130	      }
131	    }
132	    nodes.push({ label: t.label, reachable: anyStorageOk, archiveCount: count });
133	    if (!anyStorageOk) anyNodeUnreachable = true;
134	  }
135	
136	  const serverLites: ServerLite[] = servers.map((s) => ({
137	    id: s.id,
138	    vmid: s.vmid as number,
139	    hostname: s.hostname,
140	    email: s.user?.email ?? "—",
141	  }));
142	
143	  const archives = joinArchives(entries, serverLites).sort(
144	    (a, b) => (b.ctime ?? 0) - (a.ctime ?? 0)
145	  );
146	  const summary = summarizeArchives(archives);
147	
148	  const now = Date.now();
149	  const atRisk = serversWithNoRecentBackup({
150	    servers: serverLites,
151	    joined: archives,
152	    now,
153	    staleMs: BACKUP_STALE_MS,
154	  });
155	
156	  // Per-server schedule health uses the DB proof timestamp + the last CREATE
157	  // attempt, exactly like the customer server-detail page.
158	  const ids = servers.map((s) => s.id);
159	  const attempts = ids.length
160	    ? await db.job.findMany({
161	        where: { type: "BACKUP_CREATE", serverId: { in: ids } },
162	        orderBy: { createdAt: "desc" },
163	        select: { serverId: true, createdAt: true, status: true },
164	      })
165	    : [];
166	  const lastAttempt = new Map<string, { at: Date; status: string }>();
167	  for (const j of attempts) {
168	    if (j.serverId && !lastAttempt.has(j.serverId)) {
169	      lastAttempt.set(j.serverId, { at: j.createdAt, status: j.status });
170	    }
171	  }
172	
173	  const serverRows: ServerScheduleRow[] = servers.map((s) => ({
174	    id: s.id,
175	    vmid: s.vmid,
176	    hostname: s.hostname,
177	    email: s.user?.email ?? "—",
178	    nodeLabel: s.node?.name ?? null,
179	    status: s.status,
180	    autoBackup: s.autoBackup,
181	    backupIntervalHours: s.backupIntervalHours,
182	    lastAutoBackup: s.lastAutoBackup ? s.lastAutoBackup.toISOString() : null,
183	    health: backupScheduleHealth({
184	      now,
185	      autoBackup: s.autoBackup,
186	      intervalHours: s.backupIntervalHours,
187	      lastVerifiedAt: s.lastAutoBackup,
188	      lastAttempt: lastAttempt.get(s.id) ?? null,
189	    }),
190	  }));
191	
192	  return {
193	    nodes,
194	    anyNodeUnreachable,
195	    archives,
196	    summary,
197	    atRisk,
198	    servers: serverRows,
199	    staleMs: BACKUP_STALE_MS,
200	  };
201	}
202	
203	// ---------------------------------------------------------------------------
204	// Destructive: restore a live VM from one of ITS OWN archives
205	// ---------------------------------------------------------------------------
206	
207	/**
208	 * Enqueue a BACKUP_RESTORE for `volid` against `serverId`.
209	 *
210	 * The volid is NEVER trusted: it must (1) name this server's vmid structurally
211	 * and (2) actually be present in the live listing of that vmid's archives on the
212	 * server's own node. A recycled or mismatched volid restoring a stranger's root
213	 * filesystem onto this VM — handing over their databases, secrets and /etc/shadow
214	 * — is precisely the class of bug documented in lib/proxmox.ts `pickProvisionVmid`.
215	 */
216	export async function adminRequestRestore(
217	  serverId: string,
218	  volid: string
219	): Promise<{ ok?: boolean; error?: string }> {
220	  const admin = await requireArea("fleet");
221	
222	  const server = await db.server.findUnique({
223	    where: { id: serverId },
224	    include: { node: true },
225	  });
226	  if (!server) return { error: "Server not found." };
227	  if (!server.vmid) return { error: "Server has no VM yet." };
228	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
229	    return { error: "Server must be running or stopped to restore a backup." };
230	  }
231	
232	  // (1) Structural: the volid must name THIS server's vmid.
233	  const named = vmidFromVolid(volid);
234	  if (named === null || named !== server.vmid) {
235	    return { error: "That backup does not belong to this server." };
236	  }
237	
238	  // (2) Authoritative: the archive must exist for this vmid, read from the
239	  // server's own node (vmids can collide across nodes, so the primary is wrong
240	  // for a server pinned elsewhere).
241	  let owned: { volid?: string }[];
242	  try {
243	    if (server.node) {
244	      const client = pveFor({
245	        apiUrl: server.node.apiUrl,
246	        pveNode: server.node.pveNode,
247	        tokenId: server.node.tokenId,
248	        tokenSecret: server.node.tokenSecret,
249	      });
250	      const storage = server.node.isPrimary ? "backup" : (server.node.storageHdd ?? "backup");
251	      owned = await listBackupsOn(client, server.vmid, storage);
252	    } else {
253	      owned = (await listBackups(server.vmid)) as { volid?: string }[];
254	    }
255	  } catch {
256	    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
257	  }
258	  if (!owned.some((b) => b.volid === volid)) {
259	    return { error: "That backup was not found for this server." };
260	  }
261	
262	  // No concurrent job — the worker is serial and restore overwrites the disk.
263	  const pending = await db.job.count({
264	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
265	  });
266	  if (pending > 0) {
267	    return { error: "Another operation is already in progress on this server." };
268	  }
269	
270	  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
271	  await db.auditLog.create({
272	    data: { userId: admin.id, action: "admin.backup_restore", detail: `${serverId} ${volid}` },
273	  });
274	  revalidatePath("/admin/backups");
275	  return { ok: true };
276	}
