278	/** Enqueue a BACKUP_CREATE for `serverId` on the customer's behalf. */
279	export async function adminCreateBackup(
280	  serverId: string
281	): Promise<{ ok?: boolean; error?: string }> {
282	  const admin = await requireArea("fleet");
283	
284	  const server = await db.server.findUnique({ where: { id: serverId } });
285	  if (!server) return { error: "Server not found." };
286	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
287	    return { error: "Server must be running or stopped." };
288	  }
289	
290	  const pending = await db.job.count({
291	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
292	  });
293	  if (pending > 0) {
294	    return { error: "Another operation is already in progress on this server." };
295	  }
296	
297	  await db.job.create({ data: { type: "BACKUP_CREATE", serverId } });
298	  await db.auditLog.create({
299	    data: { userId: admin.id, action: "admin.backup_create", detail: serverId },
300	  });
