120	/**
121	 * Validate a proposed node's ranges/uniqueness against all other nodes.
122	 * `selfId` excludes the row being edited. Returns an error string or null.
123	 */
124	async function validateAgainstExisting(data: Omit<NodeInput, "agentToken">, selfId?: string): Promise<string | null> {
125	  if (data.ipEnd < data.ipStart) return "Guest IP range invalid: ipEnd must be ≥ ipStart.";
126	  if (data.sshPortEnd < data.sshPortStart) return "SSH port range invalid: end must be ≥ start.";
127	  if (!isValidRegion(data.provider as NodeProvider, data.region)) {
128	    return `"${data.region}" is not a known ${data.provider} datacenter code.`;
129	  }
130	
131	  const others = await db.node.findMany({
132	    where: selfId ? { id: { not: selfId } } : {},
133	    select: {
134	      name: true,
135	      publicIp: true,
136	      subnetPrefix: true,
137	      ipStart: true,
138	      ipEnd: true,
139	      sshPortStart: true,
140	      sshPortEnd: true,
141	      natChain: true,
142	      isPrimary: true,
143	    },
144	  });
145	
146	  for (const o of others) {
147	    if (o.natChain === data.natChain) {
148	      const next = data.natChain === "NXEON_FWD" ? "NXEON_FWD_N2" : `${data.natChain}_X`;
149	      return `NAT chain "${data.natChain}" is already used by node "${o.name}". Each node needs a globally unique chain (e.g. ${next}).`;
150	    }
151	    // IP ranges only collide inside the same /24 subnet.
152	    if (o.subnetPrefix === data.subnetPrefix && rangesOverlap(data.ipStart, data.ipEnd, o.ipStart, o.ipEnd)) {
153	      return `Guest IP range ${data.subnetPrefix}${data.ipStart}-${data.ipEnd} overlaps node "${o.name}" (${o.subnetPrefix}${o.ipStart}-${o.ipEnd}). Give this node its own /24, e.g. bump subnetPrefix to 10.20.N.`;
154	    }
155	    // SSH ports only collide when two nodes share the same public host.
156	    if (
157	      o.publicIp === data.publicIp &&
158	      rangesOverlap(data.sshPortStart, data.sshPortEnd, o.sshPortStart, o.sshPortEnd)
159	    ) {
160	      return `SSH port range ${data.sshPortStart}-${data.sshPortEnd} overlaps node "${o.name}" on the same host ${data.publicIp}. Use a distinct port range for co-hosted nodes.`;
161	    }
162	    if (data.isPrimary && o.isPrimary) {
163	      return `Node "${o.name}" is already the primary. Only one node can be primary.`;
164	    }
165	  }
166	  return null;
167	}
