266	/** Probe this node's node-agent, if it isn't the primary. Never throws. */
267	async function probeAgent(node: AgentNode & { isPrimary: boolean }): Promise<{ agentOk?: boolean; agentMessage?: string }> {
268	  if (node.isPrimary) return {};
269	  if (!node.agentTokenEnc) return { agentOk: false, agentMessage: "No agent token configured yet." };
270	  try {
271	    const h = await agentHealth(node);
272	    return { agentOk: !!h?.ok, agentMessage: h?.ok ? "Node-agent reachable." : "Node-agent responded, but not healthy." };
273	  } catch (e: any) {
274	    return { agentOk: false, agentMessage: String(e?.message ?? e).slice(0, 200) };
275	  }
276	}
