278	/** Live health check: hit the node's Proxmox API (and its node-agent, if any), record status + lastSeenAt. */
279	export async function testNode(id: string): Promise<TestNodeResult> {
280	  const admin = await requireAdmin();
281	  const node = await db.node.findUnique({ where: { id } });
282	  const checkedAt = new Date().toISOString();
283	  if (!node) return { ok: false, message: "Node not found.", checkedAt };
284	
285	  const client = pveFor({
286	    apiUrl: node.apiUrl,
287	    pveNode: node.pveNode,
288	    tokenId: node.tokenId,
289	    tokenSecret: node.tokenSecret,
290	  });
291	
292	  const agentResult = await probeAgent(node);
293	
294	  try {
295	    const s = await client.get(`/nodes/${client.node}/status`);
296	    await db.node.update({
297	      where: { id },
298	      data: {
299	        lastSeenAt: new Date(),
300	        // Don't override an operator-set MAINTENANCE flag with ONLINE.
301	        status: node.status === "MAINTENANCE" ? "MAINTENANCE" : "ONLINE",
302	      },
303	    });
304	    await audit(admin.id, "node.test.ok", node.name);
305	    revalidatePath("/admin/nodes");
306	    revalidatePath(`/admin/nodes/${id}`);
307	    return {
308	      ok: true,
309	      message: "Proxmox API reachable.",
310	      uptimeSec: typeof s?.uptime === "number" ? s.uptime : undefined,
311	      ramTotal: s?.memory?.total,
312	      ramUsed: s?.memory?.used,
313	      cpu: typeof s?.cpu === "number" ? s.cpu : undefined,
314	      pveVersion: typeof s?.pveversion === "string" ? s.pveversion : undefined,
315	      checkedAt,
316	      ...agentResult,
317	    };
318	  } catch (e: any) {
319	    await db.node.update({
320	      where: { id },
321	      data: { status: node.status === "MAINTENANCE" ? "MAINTENANCE" : "OFFLINE" },
322	    });
323	    await audit(admin.id, "node.test.fail", `${node.name}: ${String(e?.message ?? e).slice(0, 160)}`);
324	    revalidatePath("/admin/nodes");
325	    revalidatePath(`/admin/nodes/${id}`);
326	    return { ok: false, message: `Unreachable: ${String(e?.message ?? e).slice(0, 200)}`, checkedAt, ...agentResult };
327	  }
328	}
