282	async function powerAction(action: "start" | "stop" | "restart"): Promise<Result> {
283	  const user = await requireUser();
284	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
285	  if (!row) return { error: "You don't have a free server." };
286	
287	  const rl = checkRateLimit(`freemc:power:${user.id}`, { max: 10, windowMs: 60_000 });
288	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
289	
290	  try {
291	    const host = await freemcHost();
292	    const outcome = await withServerSsh(host, async (conn) => {
293	      // "start" always wakes a currently-stopped container, and "restart" on
294	      // one that's ALREADY stopped does too (docker's restart just starts it)
295	      // — either way that's a customer explicitly turning a container from
296	      // stopped into running, the exact path lib/freemc-capacity.ts's module
297	      // doc says this app controls and should gate (unlike mc-router's own
298	      // passive wake, which happens outside this app entirely). A restart of
299	      // an already-running container doesn't change what's committed, so it's
300	      // deliberately left ungated — same reasoning applies to "stop", which
301	      // only ever frees capacity.
302	      if (action !== "stop") {
303	        const running = await exec(
304	          conn,
305	          `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`,
306	          10_000,
307	        );
308	        const isRunning = running.code === 0 && running.stdout.trim() === "true";
309	        if (!isRunning) {
310	          const assigned = await exec(
311	            conn,
312	            `docker inspect ${shellQuote(row.containerName)} --format '{{.HostConfig.NanoCpus}} {{.HostConfig.Memory}}'`,
313	            10_000,
314	          );
315	          if (assigned.code === 0) {
316	            const [nanoCpusRaw, memBytesRaw] = assigned.stdout.trim().split(/\s+/);
317	            const cpus = (Number.parseInt(nanoCpusRaw, 10) || 0) / 1e9;
318	            const ramMb = Math.round((Number.parseInt(memBytesRaw, 10) || 0) / (1024 * 1024));
319	            const capacity = await getFreemcHostCapacity(conn);
320	            const capCheck = wouldExceedFreemcCapacity(capacity, cpus, ramMb);
321	            if (capCheck.exceeds) {
322	              return { ok: false as const, error: "Free servers are at capacity right now — try again in a few minutes." };
323	            }
324	          }
325	          // If the inspect itself failed (container missing entirely), fall
326	          // through and let the docker action below produce the real error —
327	          // no point capacity-gating a container that doesn't exist.
328	        }
329	      }
330	      const r = await exec(conn, `docker ${action} ${shellQuote(row.containerName)}`, 30_000);
331	      if (r.code !== 0) return { ok: false as const, error: r.stderr || `docker ${action} failed` };
332	      return { ok: true as const };
333	    });
334	    if (!outcome.ok) return { error: outcome.error };
335	  } catch (e) {
336	    console.error(`[free-minecraft] ${action} failed:`, e);
337	    return { error: "That didn't work — please try again in a moment." };
338	  }
339	  revalidatePath("/dashboard/free-minecraft");
340	  return {};
341	}
