357	/**
358	 * Changes the connect address. The container's own identity (containerName,
359	 * data volume) never changes — only its `mc-router.host` label does, and
360	 * labels are immutable on a running container, so this is a stop -> remove ->
361	 * recreate with the SAME name and data mount, just a new label. World data is
362	 * untouched throughout; there's a few seconds of downtime while it recreates.
363	 */
364	export async function changeFreeMinecraftSubdomain(_prev: unknown, formData: FormData): Promise<Result> {
365	  const user = await requireUser();
366	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
367	  if (!row) return { error: "You don't have a free server." };
368	
369	  const rl = checkRateLimit(`freemc:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
370	  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };
371	
372	  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
373	  const subdomainError = validateSubdomainFormat(sub);
374	  if (subdomainError) return { error: subdomainError };
375	  if (sub === row.subdomain) return {};
376	  if (!(await isSubdomainAvailable(sub, { excludeFreeMcId: row.id }))) return { error: "That name is taken — try another." };
377	
378	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
379	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
380	  // Preserve whatever game type/mode was active — moving your connect
381	  // address shouldn't reset your world or plugins.
382	  const gameTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
383	  const gameType = FREEMC_GAME_TYPES[gameTypeKey];
384	  const gameMode = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;
385	
386	  try {
387	    await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: sub } });
388	  } catch {
389	    return { error: "That name is taken — try another." };
390	  }
391	
392	  try {
393	    const host = await freemcHost();
394	    // "moved": now running under the new subdomain. "reverted": the new
395	    // address failed to boot, so it's back under the OLD one — the DB's
396	    // subdomain field must match, or the dashboard would show a "connect at"
397	    // address nothing is actually listening on.
398	    const outcome = await withServerSsh(host, async (conn) => {
399	      const applied = await recreateGameTypeContainer(conn, {
400	        containerName: row.containerName,
401	        dataPath: `/opt/freemc/servers/${row.id}`,
402	        subdomain: sub,
403	        domain,
404	        ramMb,
405	        ownerId: user.id,
406	        gameType,
407	        gameTypeKey,
408	        gameMode,
409	      });
410	      if (applied.ok) return { landed: "moved" as const };
411	      console.error("[free-minecraft] subdomain recreate failed, rolling back:", applied.error);
412	      const rolledBack = await recreateGameTypeContainer(conn, {
413	        containerName: row.containerName,
414	        dataPath: `/opt/freemc/servers/${row.id}`,
415	        subdomain: row.subdomain,
416	        domain,
417	        ramMb,
418	        ownerId: user.id,
419	        gameType,
420	        gameTypeKey,
421	        gameMode,
422	      });
423	      return rolledBack.ok
424	        ? { landed: "reverted" as const }
425	        : { landed: "broken" as const, error: rolledBack.error };
426	    });
427	
428	    if (outcome.landed !== "moved") {
429	      await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: row.subdomain } }).catch(() => {});
430	    }
431	    if (outcome.landed === "broken") throw new Error(outcome.error);
432	    if (outcome.landed === "reverted") {
433	      return { error: "That address didn't work — your server is back on its previous one." };
434	    }
435	  } catch (e) {
436	    console.error("[free-minecraft] subdomain change failed:", e);
437	    return { error: "Couldn't move your server to the new address — please try again." };
438	  }
439	  revalidatePath("/dashboard/free-minecraft");
440	  return {};
441	}
