502	
503	  const schema = schemaFor("minecraft");
504	  if (!schema) return { error: "Settings aren't available." };
505	
506	  const raw: Record<string, unknown> = {};
507	  for (const field of schema.fields) {
508	    const v = formData.get(field.key);
509	    if (v === null) continue;
510	    raw[field.key] = field.type === "bool" ? v === "true" : v;
