518	  try {
519	    const host = await freemcHost();
520	    await withServerSsh(host, async (conn) => {
521	      // Push live-appliable keys immediately via RCON (instant effect for
522	      // anyone already connected), THEN write server.properties + restart so
523	      // the change also survives the restart and applies to everyone else —
524	      // see liveRconCommandFor's own note on which keys have a real live path.
525	      for (const [k, v] of Object.entries(properties)) {
526	        const liveCmd = liveRconCommandFor(k, v);
527	        if (liveCmd) await sendRcon(conn, row.containerName, user.id, liveCmd).catch(() => {});
528	      }
529	      const write = await writeServerProperties(conn, row.containerName, properties);
530	      if (!write.ok) throw new Error(write.error || "Could not write settings.");
