532	    });
533	  } catch (e) {
534	    console.error("[free-minecraft] settings apply failed:", e);
535	    return { error: "Couldn't apply settings — please try again." };
536	  }
537	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { preset: "custom" } });
538	  revalidatePath("/dashboard/free-minecraft");
539	  return {};
540	}
