484	  // Verification flags are config-only in Phase 1 (no live DNS check).
485	  const spfVerified = formData.get("spfVerified") === "on" || formData.get("spfVerified") === "true";
486	  const dkimVerified = formData.get("dkimVerified") === "on" || formData.get("dkimVerified") === "true";
