925	  const ceilingRaw = Number(formData.get("coldemail_warmup_ceiling"));
926	  const ceiling = Number.isFinite(ceilingRaw) && ceilingRaw > 0 ? Math.min(Math.floor(ceilingRaw), 500) : 40;
927	  const thresholdRaw = Number(formData.get("coldemail_complaint_threshold"));
928	  const threshold = Number.isFinite(thresholdRaw) && thresholdRaw > 0 ? Math.min(thresholdRaw, 1) : 0.003;
929	
930	  await setSetting("coldemail_daily_cap", String(cap));
931	  await setSetting("coldemail_default_consent_basis", basis);
932	  await setSetting("coldemail_footer_disclosure", footer);
933	  await setSetting("cold_email_sending_enabled", sendingEnabled ? "true" : "false");
934	  await setSetting("cold_email_protected_domains", protectedDomains);
935	  await setSetting("coldemail_warmup_enabled", warmupEnabled ? "true" : "false");
936	  await setSetting("coldemail_warmup_ceiling", String(ceiling));
937	  await setSetting("coldemail_complaint_threshold", String(threshold));
938	
939	  // Phase 3 burn thresholds (fractions, 0–1). Blank → keep the current/default.
940	  const frac = (key: string, fallback: number) => {
