1231	  const id = String(formData.get("id") ?? "").trim() || null;
1232	  const sendingDomainId = String(formData.get("sendingDomainId") ?? "").trim();
1233	  const email = normalizeEmail(String(formData.get("email") ?? ""));
1234	  const provider = pick(PROVIDERS, formData.get("provider"), "SMTP");
1235	  const strategy = pick(STRATEGIES, formData.get("strategy"), "STANDARD") as WarmupStrategyKey;
1236	  const warmupMode = pick(MODES, formData.get("warmupMode"), "HYBRID");
1237	
1238	  if (!sendingDomainId) return { error: "Pick a sending domain." };
1239	  if (!email || !emailSchema.safeParse(email).success) return { error: "Enter a valid mailbox address." };
1240	  const domain = await db.sendingDomain.findUnique({ where: { id: sendingDomainId }, select: { id: true } });
1241	  if (!domain) return { error: "Sending domain not found." };
1242	
1243	  // Warmup plan: default to the strategy preset, allow explicit overrides.
1244	  const preset = WARMUP_PRESETS[strategy];
1245	  const plan = normalizePlan({
1246	    startCap: capInt(formData.get("startCap"), 1, 200, preset.startCap),
1247	    targetCap: capInt(formData.get("targetCap"), 1, 500, preset.targetCap),
1248	    rampDays: capInt(formData.get("rampDays"), 1, 90, preset.rampDays),
1249	  });
1250	  const dailyCap = capInt(formData.get("dailyCap"), 1, 500, plan.targetCap);
1251	  const minGapSeconds = capInt(formData.get("minGapSeconds"), 30, 3600, 100);
1252	
1253	  // ---- Overhaul Phase 1: per-mailbox SMTP + IMAP credentials ----
1254	  //
1255	  // Hosts/ports/users/TLS are always written. Passwords are WRITE-ONLY: a blank
1256	  // password field leaves the stored (encrypted) value untouched, so editing an
1257	  // inbox never wipes its creds and the plaintext is never echoed back to the form.
1258	  // Passwords are encrypted with lib/crypto-box before they ever touch the DB.
1259	  const smtpHost = String(formData.get("smtpHost") ?? "").trim().slice(0, 255);
1260	  const smtpUser = String(formData.get("smtpUser") ?? "").trim().slice(0, 255);
1261	  const smtpPassRaw = String(formData.get("smtpPass") ?? "");
1262	  const smtpPort = capInt(formData.get("smtpPort"), 1, 65535, 587);
1263	  const smtpTls = formData.get("smtpTls") === "on" || formData.get("smtpTls") === "true";
1264	  const imapHost = String(formData.get("imapHost") ?? "").trim().slice(0, 255);
1265	  const imapUser = String(formData.get("imapUser") ?? "").trim().slice(0, 255);
1266	  const imapPassRaw = String(formData.get("imapPass") ?? "");
1267	  const imapPort = capInt(formData.get("imapPort"), 1, 65535, 993);
1268	  const imapTls = formData.get("imapTls") == null ? true : formData.get("imapTls") === "on" || formData.get("imapTls") === "true";
1269	
1270	  const data = {
1271	    sendingDomainId,
1272	    email,
1273	    provider,
1274	    strategy,
1275	    warmupMode,
1276	    startCap: plan.startCap,
1277	    targetCap: plan.targetCap,
1278	    rampDays: plan.rampDays,
1279	    dailyCap,
1280	    minGapSeconds,
1281	    smtpHost,
1282	    smtpPort,
1283	    smtpUser,
1284	    smtpTls,
1285	    imapHost,
1286	    imapPort,
1287	    imapUser,
1288	    imapTls,
1289	  };
1290	  // Only overwrite an encrypted password when a new one was actually typed.
1291	  const passData: { smtpPassEnc?: string; imapPassEnc?: string } = {};
1292	  if (smtpPassRaw) passData.smtpPassEnc = encryptSecret(smtpPassRaw);
1293	  if (imapPassRaw) passData.imapPassEnc = encryptSecret(imapPassRaw);
1294	
1295	  try {
1296	    if (id) {
1297	      await db.inbox.update({ where: { id }, data: { ...data, ...passData } });
1298	    } else {
1299	      await db.inbox.create({ data: { ...data, ...passData, status: "WARMING", currentRampCap: plan.startCap } });
1300	    }
1301	  } catch (err) {
1302	    await logEvent("error", "coldemail.inbox.save", { message: String(err) });
1303	    return { error: "Could not save the inbox (is that address already registered?)." };
1304	  }
1305	  revalidatePath("/admin/coldemail/domains");
1306	  revalidatePath("/admin/coldemail/warming");
1307	  return { ok: true };
1308	}
