3	// Server actions for the Matrix multi-console workspace.
4	//
5	// EVERY export of a "use server" file is a public network endpoint, so every
6	// action here authenticates (requireUser) and ownership-checks the server id it
7	// is handed, INSIDE the function, before doing anything — one customer's console
8	// must never reach another customer's server.
9	//
10	// Flow (chat console, plan-then-approve preserved):
11	//   planConsoleBuild(serverId, prompt, images[]) — authenticates, ownership-checks,
12	//     asks Claude (BYOK, MULTIMODAL) for a command plan SYNCHRONOUSLY, stores it,
13	//     and leaves the build AWAITING_APPROVAL. NOTHING runs on the server here.
14	//   -> approveBuild(id)  (lib/actions-claude.ts, CAS-guarded) enqueues the worker
15	//        EXECUTE job, which runs the approved plan over SSH under its denylist.
16	//   -> rejectBuild(id)   marks it FAILED; nothing runs.
17	//
18	// Planning is done in the action (not the worker) so pasted images can be wired
19	// into the message — the worker's planner is string-only. Execution still goes
20	// through the existing worker + denylist, so the SSH safety guard is unchanged.
21	
22	import { db } from "./db";
23	import { requireUser } from "./auth";
24	import { effectiveKeyFor, platformKeyConfigured } from "./anthropic";
25	import { serverRootPassword } from "./sftp";
26	import { getSettingBool } from "./settings";
27	import {
28	  buildUserContent,
29	  parseImageDataUrl,
30	  parsePlanReply,
31	  validateImages,
32	  MAX_CONSOLES,
33	  type ConsoleImage,
34	  type AnthropicContentBlock,
35	} from "./claude-console-core";
36	
37	const MAX_PROMPT_CHARS = 2000;
38	const MIN_PROMPT_CHARS = 8;
39	
40	// A workspace holds up to MAX_CONSOLES consoles, each of which can have a build
41	// in flight — so the active-build ceiling matches the console ceiling. A short
42	// window rate-limit keeps a burst (e.g. a 6-way mirror) sane.
43	const MAX_ACTIVE_CONSOLE_BUILDS = MAX_CONSOLES;
44	const RATE_WINDOW_MS = 60_000;
45	const MAX_BUILDS_PER_WINDOW = 12;
46	
47	// Statuses that mean a build is not yet finished — used for in-flight accounting.
48	const ACTIVE_STATUSES = ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"] as const;
49	
50	// Kept in sync with worker/claude.ts CLAUDE_MAX_COMMANDS — the plan is capped to
51	// the same length the worker will execute.
52	const CLAUDE_MAX_COMMANDS = 20;
53	
54	const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
55	const MODEL = "claude-opus-4-8";
56	// Stay comfortably under a typical 60s reverse-proxy read timeout.
57	const PLAN_TIMEOUT_MS = 55_000;
58	
59	const PLAN_SYSTEM_PROMPT = `You are an expert Linux server administrator. You are given a goal for a SINGLE Debian/Ubuntu server that you operate on over SSH as root. The goal may include screenshots or images for context. Produce a PLAN — do NOT run anything.
60	
61	Output ONLY a JSON array of steps and NOTHING else (no markdown, no backticks, no prose before or after). Each step is an object:
62	{"cmd": "<one non-interactive shell command>", "intent": "<short plain-English explanation of what it does and why>"}
63	
64	Rules for the plan:
65	- Operate ONLY on this one server. Never touch other hosts, networks, or cloud APIs.
66	- Commands must be non-interactive: use flags like -y and DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
67	- NON-DESTRUCTIVE ONLY. Absolutely no whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff/halt, no user/password changes, no disabling SSH.
68	- Keep each command self-contained and idempotent where possible.
69	- Prefer standard packages and services (apt, systemctl, nginx, ufw, etc.).
70	- At most ${CLAUDE_MAX_COMMANDS} steps. If the goal cannot be met safely, return an empty array [].`;
71	
72	/** Multimodal plan request. Never throws to the caller — returns text or throws internally-caught. */
73	async function callClaudePlan(
74	  apiKey: string,
75	  content: AnthropicContentBlock[]
76	): Promise<string> {
77	  const controller = new AbortController();
78	  const timer = setTimeout(() => controller.abort(), PLAN_TIMEOUT_MS);
79	  let res: Response;
80	  try {
81	    res = await fetch(ANTHROPIC_URL, {
82	      method: "POST",
83	      headers: {
84	        "content-type": "application/json",
85	        "x-api-key": apiKey,
86	        "anthropic-version": "2023-06-01",
87	      },
88	      body: JSON.stringify({
89	        model: MODEL,
90	        max_tokens: 4096,
91	        system: PLAN_SYSTEM_PROMPT,
92	        messages: [{ role: "user", content }],
93	      }),
94	      signal: controller.signal,
95	    });
96	  } finally {
97	    clearTimeout(timer);
98	  }
99	  if (!res.ok) {
100	    const body = await res.text().catch(() => "");
101	    throw new Error(`Anthropic API ${res.status}: ${body.slice(0, 300)}`);
102	  }
103	  const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
104	  return (data.content ?? [])
105	    .filter((b) => b.type === "text" && typeof b.text === "string")
106	    .map((b) => b.text as string)
107	    .join("")
108	    .trim();
109	}
