111	export type PlanConsoleResult = { error?: string; buildId?: string };
112	
113	/**
114	 * Plan a build for one console: authenticate, ownership-check the server, ask
115	 * Claude (with any pasted images) for a command plan, and store it as
116	 * AWAITING_APPROVAL. Nothing runs on the server. `imageDataUrls` are browser
117	 * `data:` URLs; unparseable ones are dropped.
118	 */
119	export async function planConsoleBuild(
120	  serverId: string,
121	  prompt: string,
122	  imageDataUrls?: string[],
123	  mirrorGroupId?: string | null,
124	  title?: string | null
125	): Promise<PlanConsoleResult> {
126	  const user = await requireUser();
127	
128	  // Feature flag: the whole "Build with AI" surface can be switched off.
129	  if (!(await getSettingBool("feature_claude_builder", true))) {
130	    return { error: "Build with AI is currently unavailable." };
131	  }
132	
133	  const clean = (prompt ?? "").trim();
134	  if (clean.length < MIN_PROMPT_CHARS) {
135	    return { error: "Please describe what you'd like to build (a sentence or two)." };
136	  }
137	  if (clean.length > MAX_PROMPT_CHARS) {
138	    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
139	  }
140	
141	  // Parse + validate any pasted images (drop anything that is not a supported
142	  // base64 image data URL).
143	  const images: ConsoleImage[] = [];
144	  for (const url of imageDataUrls ?? []) {
145	    const img = parseImageDataUrl(url);
146	    if (img) images.push(img);
147	  }
148	  const imgCheck = validateImages(images);
149	  if (!imgCheck.ok) return { error: imgCheck.error };
150	
151	  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
152	  const owner = await db.user.findUnique({
153	    where: { id: user.id },
154	    select: { anthropicKeyEnc: true },
155	  });
156	  const apiKey = effectiveKeyFor(owner);
157	  if (!apiKey) {
158	    return { error: "Add your Anthropic API key in Settings to use Build with AI." };
159	  }
160	
161	  // Ownership: the server must belong to THIS user. Ownership-checked from the id
162	  // that was passed in — never a bare findUnique whose result is then trusted.
163	  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
164	  if (!server) return { error: "Server not found." };
165	  if (server.status !== "RUNNING") {
166	    return { error: "The server must be running to build on it." };
167	  }
168	  if (!server.ipAddress || !serverRootPassword(server)) {
169	    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
170	  }
171	
172	  // Rate + concurrency sanity, scoped to the user.
173	  const active = await db.claudeBuild.count({
174	    where: { userId: user.id, status: { in: [...ACTIVE_STATUSES] } },
175	  });
176	  if (active >= MAX_ACTIVE_CONSOLE_BUILDS) {
177	    return { error: `You already have ${MAX_ACTIVE_CONSOLE_BUILDS} builds in flight. Finish or clear some before starting another.` };
178	  }
179	  const recent = await db.claudeBuild.count({
180	    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
181	  });
182	  if (recent >= MAX_BUILDS_PER_WINDOW) {
183	    return { error: "Too many builds started just now — please wait a minute and try again." };
184	  }
185	
186	  // Ask Claude for the plan (BYOK, multimodal). This is the only external call.
187	  let reply: string;
188	  try {
189	    reply = await callClaudePlan(apiKey, buildUserContent(clean, images));
190	  } catch (e: unknown) {
191	    const msg = e instanceof Error ? e.message : String(e);
192	    return { error: `Planning failed: ${msg.slice(0, 200)}` };
193	  }
194	
195	  const plan = parsePlanReply(reply);
196	  if (!plan) {
197	    return { error: "Claude didn't return a usable plan for this goal. Try rephrasing it." };
198	  }
199	  const capped = plan.slice(0, CLAUDE_MAX_COMMANDS);
200	
201	  // Store the build already planned + awaiting approval (approved=false). The
202	  // worker's plan phase is skipped; approveBuild will enqueue the EXECUTE job.
203	  const build = await db.claudeBuild.create({
204	    data: {
205	      userId: user.id,
206	      serverId,
207	      prompt: clean,
208	      status: "AWAITING_APPROVAL",
209	      approved: false,
210	      plan: JSON.stringify(capped),
211	      mirrorGroupId: mirrorGroupId?.trim() ? mirrorGroupId.trim() : null,
212	      title: title?.trim() ? title.trim() : null,
213	    },
214	  });
215	
216	  await db.auditLog
217	    .create({
218	      data: {
219	        userId: user.id,
220	        action: "server.claude_console_plan",
221	        detail: `${serverId} ${build.id}${images.length ? ` img=${images.length}` : ""}${
222	          mirrorGroupId ? ` mirror=${mirrorGroupId}` : ""
223	        }`,
224	      },
225	    })
226	    .catch(() => {});
227	
228	  return { buildId: build.id };
229	}
