1	/**
2	 * Shared, injection-safe SSH execution foundation for the customer control
3	 * panel (websites, databases, one-click apps, cron & services).
4	 *
5	 * This is a plain server-side module (NO "use server", no client imports) so it
6	 * can be used by both the inline read helpers (lib/cpanel-inline.ts) and the
7	 * worker executors (worker/websites|databases|apps|services.ts). It NEVER runs
8	 * in the browser — the customer's root credentials stay on the server.
9	 *
10	 * It mirrors the hardening in worker/migrate-real.ts on two axes:
11	 *
12	 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret value that will be
13	 *      interpolated into a remote command MUST match a shell-inert allowlist
14	 *      (regexes below contain no quotes/spaces/metacharacters/newlines) or the
15	 *      operation FAILS. We reject — never sanitize. Callers validate up front
16	 *      with the `assert*` helpers so a bad value can never reach a shell.
17	 *
18	 *   2. SECRETS NEVER TOUCH A COMMAND STRING. Generated DB / app passwords are
19	 *      written to the far side via a command's STDIN (`execInput`) or an SFTP
20	 *      file — never as an argv token. Command strings reference only file paths
21	 *      or values that passed the allowlist.
22	 *
23	 * Connection target + root password derivation is identical to lib/sftp.ts and
24	 * worker/ssl.ts (dedicated IP → own IP:22, else PUBLIC_IP:sshPort; user root).
25	 */
26	import { Client, type ClientChannel } from "ssh2";
27	import { randomBytes } from "node:crypto";
28	import { connectionTarget, serverRootPassword, type SftpServer } from "./sftp";
29	
30	// ---- Timeouts -------------------------------------------------------------
31	export const SSH_CONNECT_TIMEOUT_MS = 15_000;
32	/** Quick inline reads (list/status/snapshot) — kept short so a slow box can't
33	 *  wedge a page render. */
34	export const QUICK_TIMEOUT_MS = 12_000;
35	/** Small mutating commands (write a vhost, create a DB, edit crontab). */
36	export const SETUP_TIMEOUT_MS = 60_000;
37	/** Long installs (php-fpm, an engine, an app download). */
38	export const INSTALL_TIMEOUT_MS = Number(process.env.CPANEL_INSTALL_TIMEOUT_MS ?? 15 * 60_000);
39	
40	// ---- Strict allowlist validators (throw on any violation) -----------------
41	// Every charset below is deliberately shell-inert.
42	export const DOMAIN_RE =
43	  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
44	/** DB / DB-user identifier: letters, digits, underscore. */
45	export const IDENT_RE = /^[A-Za-z0-9_]{1,32}$/;
46	/** PHP version like 8.3 / 7.4. */
47	export const PHP_VERSION_RE = /^\d\.\d$/;
48	/** systemd unit name (bare service name we control from a fixed list). */
49	export const SERVICE_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;
50	/** Absolute path with a safe charset, no traversal / double slash. */
51	export const PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
52	/** A single crontab time field: digits, * , - , / and commas only. */
53	export const CRON_FIELD_RE = /^[0-9*,/-]{1,64}$/;
54	/** App slug from our fixed catalog. */
55	export const SLUG_RE = /^[a-z][a-z0-9-]{0,31}$/;
56	
57	export function assert(cond: unknown, msg: string): asserts cond {
58	  if (!cond) throw new Error(msg);
59	}
60	
61	export function assertDomain(d: string): void {
62	  assert(typeof d === "string" && DOMAIN_RE.test(d), `Unsupported domain: ${d}`);
63	}
64	export function assertIdent(v: string, what: string): void {
65	  assert(typeof v === "string" && IDENT_RE.test(v), `Unsupported ${what}: ${v}`);
66	}
67	export function assertPhp(v: string): void {
68	  assert(typeof v === "string" && PHP_VERSION_RE.test(v), `Unsupported PHP version: ${v}`);
69	}
70	export function assertService(v: string): void {
71	  assert(typeof v === "string" && SERVICE_RE.test(v), `Unsupported service: ${v}`);
72	}
73	export function assertPath(p: string): void {
74	  assert(
75	    typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//"),
76	    `Unsupported path: ${p}`
77	  );
78	}
79	export function assertSlug(s: string): void {
80	  assert(typeof s === "string" && SLUG_RE.test(s), `Unsupported app: ${s}`);
81	}
82	
83	/**
84	 * Validate a 5-field cron schedule. Each field must match CRON_FIELD_RE, so the
85	 * whole expression is shell-inert (no metacharacters). Returns the normalized
86	 * single-spaced expression, or throws.
87	 */
88	export function assertCronSchedule(schedule: string): string {
89	  assert(typeof schedule === "string", "Invalid schedule.");
90	  const fields = schedule.trim().split(/\s+/);
91	  assert(fields.length === 5, "A cron schedule must have exactly 5 fields (min hour dom mon dow).");
92	  for (const f of fields) assert(CRON_FIELD_RE.test(f), `Unsupported cron field: ${f}`);
93	  return fields.join(" ");
94	}
95	
96	/**
97	 * Defensive POSIX single-quote. Even allowlisted values are quoted when they are
98	 * interpolated, so a value that (against expectation) slipped through has no
99	 * shell effect. NEVER used for secrets — those go through STDIN/SFTP.
100	 */
101	export function shellQuote(s: string): string {
102	  return `'${String(s).replace(/'/g, `'\\''`)}'`;
103	}
104	
105	// ---- SSH plumbing ---------------------------------------------------------
106	
107	export type SshResult = { code: number | null; stdout: string; stderr: string };
108	
109	/**
110	 * Run one command on an already-connected client, capturing output + exit code.
111	 * Rejects if the command exceeds `timeoutMs` (the channel is torn down so a hung
112	 * remote command can't wedge the worker/page).
113	 */
114	export function exec(conn: Client, command: string, timeoutMs: number): Promise<SshResult> {
115	  return new Promise((resolve, reject) => {
116	    conn.exec(command, (err, stream: ClientChannel) => {
117	      if (err) return reject(err);
118	      let stdout = "";
119	      let stderr = "";
120	      let settled = false;
121	      const timer = setTimeout(() => {
122	        if (settled) return;
123	        settled = true;
124	        try {
125	          stream.close();
126	        } catch {
127	          /* best effort */
128	        }
129	        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
130	      }, timeoutMs);
131	      stream
132	        .on("close", (code: number | null) => {
133	          if (settled) return;
134	          settled = true;
135	          clearTimeout(timer);
136	          resolve({ code, stdout, stderr });
137	        })
138	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
139	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
140	    });
141	  });
142	}
143	
144	/**
145	 * Run a command and stream `input` into its STDIN — used to write a secret into
146	 * a file on the far side (`cat > file`) without the secret ever appearing as a
147	 * command-line argument. Mirrors worker/migrate-real.ts execRemoteInput.
148	 */
149	export function execInput(
150	  conn: Client,
151	  command: string,
152	  input: string,
153	  timeoutMs: number
154	): Promise<SshResult> {
155	  return new Promise((resolve, reject) => {
156	    conn.exec(command, (err, stream: ClientChannel) => {
157	      if (err) return reject(err);
158	      let stdout = "";
159	      let stderr = "";
160	      let settled = false;
161	      const timer = setTimeout(() => {
162	        if (settled) return;
163	        settled = true;
164	        try {
165	          stream.close();
166	        } catch {
167	          /* best effort */
168	        }
169	        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
170	      }, timeoutMs);
171	      stream
172	        .on("close", (code: number | null) => {
173	          if (settled) return;
174	          settled = true;
175	          clearTimeout(timer);
176	          resolve({ code, stdout, stderr });
177	        })
178	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
179	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
180	      stream.end(input);
181	    });
182	  });
183	}
