356	/**
357	 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
358	 * the cap so we never buffer an unbounded file into memory / the editor.
359	 */
360	export async function readFileText(
361	  server: SftpServer,
362	  path: string,
363	  maxBytes: number
364	): Promise<string> {
365	  if (SANDBOX) {
366	    const node = simResolve(server.id, path);
367	    if (!node) throw new Error("No such file.");
368	    if (node.type !== "file") throw new Error("Not a file.");
369	    if (Buffer.byteLength(node.content) > maxBytes) {
370	      throw new Error("File is too large to edit in the browser.");
371	    }
372	    return node.content;
373	  }
374	
375	  return withSftp(server, async (client) => {
376	    const s = await client.stat(path);
377	    if (s.isDirectory) throw new Error("Not a file.");
378	    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
379	    const buf = (await client.get(path)) as Buffer;
380	    return buf.toString("utf8");
381	  });
382	}
383	
384	export async function writeFileText(
385	  server: SftpServer,
386	  path: string,
387	  content: string
388	): Promise<void> {
389	  if (SANDBOX) {
390	    const loc = simParent(server.id, path);
391	    if (!loc) throw new Error("Invalid path.");
392	    const existing = loc.parent.children[loc.name];
393	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
394	    loc.parent.children[loc.name] = {
395	      type: "file",
396	      mtime: Date.now(),
397	      mode: existing?.type === "file" ? existing.mode : 0o644,
398	      content,
399	    };
400	    return;
401	  }
402	
403	  await withSftp(server, async (client) => {
404	    await client.put(Buffer.from(content, "utf8"), path);
405	  });
406	}
407	
408	export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
409	  if (SANDBOX) {
410	    const loc = simParent(server.id, path);
411	    if (!loc) throw new Error("Invalid path.");
412	    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
413	    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
414	    return;
415	  }
416	
417	  await withSftp(server, async (client) => {
418	    await client.mkdir(path, false);
419	  });
420	}
421	
422	export async function renamePath(
423	  server: SftpServer,
424	  from: string,
425	  to: string
426	): Promise<void> {
427	  if (SANDBOX) {
428	    const src = simResolve(server.id, from);
429	    if (!src) throw new Error("No such file or directory.");
430	    const dst = simParent(server.id, to);
431	    if (!dst) throw new Error("Invalid destination.");
432	    if (dst.parent.children[dst.name]) {
433	      throw new Error("A file or folder with that name already exists.");
434	    }
435	    const srcLoc = simParent(server.id, from);
436	    if (!srcLoc) throw new Error("Cannot rename the root.");
437	    delete srcLoc.parent.children[srcLoc.name];
438	    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
439	    return;
440	  }
441	
442	  await withSftp(server, async (client) => {
443	    await client.rename(from, to);
444	  });
445	}
446	
447	/** Remove a file, or recursively remove a directory. */
448	export async function removePath(server: SftpServer, path: string): Promise<void> {
449	  if (SANDBOX) {
450	    const loc = simParent(server.id, path);
451	    if (!loc) throw new Error("Cannot remove the root.");
452	    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
453	    delete loc.parent.children[loc.name];
454	    return;
455	  }
456	
457	  await withSftp(server, async (client) => {
458	    const s = await client.stat(path);
459	    if (s.isDirectory) {
460	      await client.rmdir(path, true); // recursive
461	    } else {
462	      await client.delete(path);
463	    }
464	  });
465	}
466	
467	export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
468	  if (SANDBOX) {
469	    const node = simResolve(server.id, path);
470	    if (!node) throw new Error("No such file or directory.");
471	    node.mode = mode & 0o777;
472	    return;
473	  }
474	
475	  await withSftp(server, async (client) => {
476	    await client.chmod(path, mode & 0o777);
477	  });
478	}
