500	/** Write a Buffer to a path (used by the upload endpoint). */
501	export async function writeFileBuffer(
502	  server: SftpServer,
503	  path: string,
504	  data: Buffer
505	): Promise<void> {
506	  if (SANDBOX) {
507	    const loc = simParent(server.id, path);
508	    if (!loc) throw new Error("Invalid path.");
509	    const existing = loc.parent.children[loc.name];
510	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
511	    loc.parent.children[loc.name] = {
512	      type: "file",
513	      mtime: Date.now(),
514	      mode: existing?.type === "file" ? existing.mode : 0o644,
515	      content: data.toString("utf8"),
516	    };
517	    return;
518	  }
519	
