1	/**
2	 * Shared name rules for every `<name>.play.nxeon.cloud` Minecraft subdomain —
3	 * free-tier (`FreeMinecraftServer.subdomain`) and paid-tier (`Server.subdomain`)
4	 * alike, since both share the same DNS namespace. Extracted from
5	 * lib/actions-free-minecraft.ts (the free tier had this first) so the two
6	 * products can never drift on what a "valid" or "reserved" name is.
7	 *
8	 * Deliberately zero-dependency (no `./db`) so it's safe to import from a
9	 * client component (e.g. the order wizard's live format check) without
10	 * pulling the Prisma client into the browser bundle — lib/game-subdomain.ts
11	 * re-exports these plus the DB-backed availability check for server-only code.
12	 */
13	export const SUBDOMAIN_RE = /^[a-z0-9]([a-z0-9-]{1,18}[a-z0-9])?$/;
14	export const RESERVED_SUBDOMAINS = new Set(["www", "api", "admin", "mc", "play", "test", "server", "router"]);
15	
16	/** Format/reserved-word check only — no DB access. Returns an error message, or null if valid. */
17	export function validateSubdomainFormat(sub: string): string | null {
18	  if (!SUBDOMAIN_RE.test(sub) || RESERVED_SUBDOMAINS.has(sub)) {
19	    return "Pick a name: 3-20 lowercase letters, numbers, or hyphens, not a reserved word.";
20	  }
21	  return null;
22	}
